/**
 * tests/config/env.js
 *
 * Environment configuration sourced from perf-config.json environment.base_url.
 * Override BASE_URL at runtime: k6 run -e BASE_URL=http://staging:3000 script.js
 *
 * Generated by: perf-build
 * Group: {group_name}
 * Date: {generated_date}
 */

/**
 * Base URL of the SUT.
 * Reads from environment variable first, falls back to the value from perf-config.json.
 *
 * Usage:
 *   import { BASE_URL, DEFAULT_HEADERS } from '../../tests/config/env.js';
 */
export const BASE_URL = __ENV.BASE_URL || "{base_url}";

/**
 * Default request headers applied to all requests unless overridden.
 * Auth header is NOT included here — it is set per-request after token acquisition.
 */
export const DEFAULT_HEADERS = {
  "Content-Type": "application/json",
};

/**
 * Test metadata — written into request tags for Grafana filtering.
 */
export const TEST_META = {
  group: "{group_name}",
  test_type: "{test_type}",
};
